output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file aisles between shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "park_cart_at_narrow_aisle_mouth",
    "text": "Before shopping in a single-file shelf aisle, the cart must be parked at the wide aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "singleFileAisleMouth",
          "hasCart"
        ]
      },
      "discharge": "parkCartAtMouth"
    }
  },
  {
    "id": "retrieve_cart_after_single_file_aisle",
    "text": "After returning from a single-file shelf aisle, the shopper must retrieve the parked cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "leaveSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "S"
            ]
          },
          "post": "singleFileAisleMouth"
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leaveSingleFileAisle",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "cart_required_for_broad_shelf_service",
    "text": "Shelf interactions from broad aisles must be performed with a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "broadShelfServiceCell": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            },
            {
              "ge": [
                "freeWidthH",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "broadShelfServiceCell",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "exit_only_with_cart",
    "text": "A shopper may not leave the supermarket without the cart.",
    "abstraction": {
      "state_properties": {
        "exitCell": "at(11,7)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exitCell",
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "eastbound_cart_flow_in_wide_aisles",
    "text": "When pushing a cart in wide aisles, shoppers must not travel west against the one-way flow.",
    "abstraction": {
      "state_properties": {
        "wideCartAisle": {
          "and": [
            "hasCart",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideCartAisle",
          "W"
        ]
      }
    }
  },
  {
    "id": "take_cart_at_entrance_bay",
    "text": "On entering the store, the shopper is obliged to take a cart from the entrance cart bay.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)"
      },
      "events": {
        "takeCart": {
          "pre": {
            "and": [
              "cartBay",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCart"
    }
  },
  {
    "id": "no_pedestrian_roaming_away_from_narrow_aisles",
    "text": "After parking a cart, a shopper without a cart may move only into the single-file shelf aisle or remain at the aisle mouth to retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "entranceOrCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "allowedNoCartZone": {
          "or": [
            "entranceOrCartBay",
            "singleFileShelfAisle",
            "singleFileAisleMouth"
          ]
        }
      },
      "events": {
        "enterSingleFileAisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileAisleMouth",
              "N"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "MOVE",
          {
            "not": "allowedNoCartZone"
          },
          {
            "not": "enterSingleFileAisle"
          }
        ]
      }
    }
  }
]
